import zlib,re
data=open('contrato_prestacao_servicos_pj.pdf','rb').read()
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    try:
        s=zlib.decompress(m.group(1))
        txt=b' '.join(re.findall(rb'\((.*?)\)', s))
        print(txt.decode('latin-1'))
    except Exception: pass
")"}

